package com.example

/**
 * Curated, 100% syllabus-aligned, distinct Flashcards for Commerce & Accounting (ව්‍යාපාර හා ගිණුම්කරණය).
 * Part 1: Categories 1 to 10 (20 distinct questions per category).
 * Strictly guarantees no repeated questions within the same category or across different categories.
 */
object FlashcardBankCommerceSetsPart1 {

  fun getCard(setNum: Int, cardNum: Int): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      1 -> set1[(c - 1) % set1.size]
      2 -> set2[(c - 1) % set2.size]
      3 -> set3[(c - 1) % set3.size]
      4 -> set4[(c - 1) % set4.size]
      5 -> set5[(c - 1) % set5.size]
      6 -> set6[(c - 1) % set6.size]
      7 -> set7[(c - 1) % set7.size]
      8 -> set8[(c - 1) % set8.size]
      9 -> set9[(c - 1) % set9.size]
      10 -> set10[(c - 1) % set10.size]
      else -> FlashcardBankCommerceSetsPart2.getCard(setNum, cardNum)
    }
  }

  // --- SET 1: ව්‍යාපාර පසුබිම, අවශ්‍යතා & උවමනා ---
  private val set1 = listOf(
    CardContentTuple("ව්‍යාපාරයක් (Business) යනු කුමක්ද?", "මිනිස් අවශ්‍යතා සහ උවමනා තෘප්තිමත් කරමින් ලාභ ලැබීමේ හෝ සමාජ සත්කාරක අරමුණින් භාණ්ඩ හා සේවා නිෂ්පාදනය සහ බෙදාහැරීමේ ආර්ථික ක්‍රියාවලියයි.", "ආර්ථිකයේ ජීවනාලියයි.", "අවශ්‍යතා/උවමනා තෘප්තිමත් කිරීම"),
    CardContentTuple("මිනිස් අවශ්‍යතා (Needs) සහ උවමනා (Wants) අතර වෙනස කුමක්ද?", "අවශ්‍යතා = මිනිසාට ජීවත්වීම සඳහා අත්‍යවශ්‍ය මූලික දෑ (ආහාර, ඇඳුම්, නිවාස, සෞඛ්‍යය, ආරක්ෂාව - සීමිතය, පොදුය).\nඋවමනා = එම අවශ්‍යතා සපුරා ගන්නා විවිධ වූ ආකාර (බත්, නූඩ්ල්ස්, පීසා - අසීමිතය, සංස්කෘතිය අනුව වෙනස් වේ).", "අවශ්‍යතා සීමිතයි, උවමනා අසීමිතයි.", "අවශ්‍යතා (මූලික) vs උවමනා (විවිධාකාර)"),
    CardContentTuple("නිෂ්පාදන සාධක (Factors of Production) 4 සහ ඒවායේ ප්‍රතිලාභ (ප්‍රතිලාභී ආදායම්) මොනවාද?", "1. භූමිය (ස්වභාවික සම්පත්) -> කුලිය (Rent)\n2. ශ්‍රමය (කායික/මානසික) -> වැටුප් (Wages)\n3. ප්‍රාග්ධනය (මිනිසා තැනූ උපකරණ) -> පොලිය (Interest)\n4. ව්‍යවසායකත්වය (සම්පත් ඒකාබද්ධ කිරීම) -> ලාභය (Profit).", "ඕනෑම නිෂ්පාදනයක මූලික සාධක 4යි.", "භූමිය, ශ්‍රමය, ප්‍රාග්ධනය, ව්‍යවසායකත්වය"),
    CardContentTuple("ව්‍යවසායකයෙකු (Entrepreneur) සතු සුවිශේෂී ලක්ෂණ 3ක් මොනවාද?", "1. අවදානම් භාරගැනීමේ හැකියාව 2. නවෝත්පාදන (Innovation) හඳුන්වා දීම 3. නායකත්වය සහ ආත්ම විශ්වාසය.", "ව්‍යාපාරික අදහස් යථාර්ථයක් කරයි.", "අවදානම, නවෝත්පාදනය, නායකත්වය"),
    CardContentTuple("භාණ්ඩ (Goods) සහ සේවා (Services) අතර වෙනස කුමක්ද?", "භාණ්ඩ = භෞතික පැවැත්මක් ඇති, ස්පර්ශ කළ හැකි, ගබඩා කළ හැකි ද්‍රව්‍ය (පොත්, පෑන්, පාන්).\nසේවා = භෞතික පැවැත්මක් නැති, ස්පර්ශ කළ නොහැකි, ගබඩා කළ නොහැකි ක්‍රියාකාරකම් (වෛද්‍ය සේවය, බැංකු සේවය, ඉගැන්වීම).", "දෘශ්‍ය vs අදෘශ්‍යමාන ප්‍රතිලාභ.", "භාණ්ඩ (දෘශ්‍ය) vs සේවා (අදෘශ්‍ය)"),
    CardContentTuple("ව්‍යාපාරයක අභ්‍යන්තර පරිසරය (Internal Environment) සහ බාහිර පරිසරය (External Environment) යනු කුමක්ද?", "අභ්‍යන්තර පරිසරය = ව්‍යාපාරයට පාලනය කළ හැකි සාධක (හිමිකරුවන්, කළමනාකරුවන්, සේවකයින්, සංවිධාන ව්‍යුහය).\nබාහිර පරිසරය = ව්‍යාපාරයට පාලනය කළ නොහැකි බාහිර බලවේග (ආර්ථික, දේශපාලන, නීතිමය, තාක්ෂණික, තරගකාරී).", "PESTLE සාධක බාහිර පරිසරයයි.", "අභ්‍යන්තර (පාලිත) vs බාහිර (නොපාලිත)"),
    CardContentTuple("ව්‍යාපාරයක පාර්ශ්වකරුවන් (Stakeholders) යනු කවුරුන්ද? ප්‍රධාන පාර්ශ්වකරුවන් 4ක් නම් කරන්න.", "ව්‍යාපාරයේ පැවැත්ම, තීරණ සහ ක්‍රියාකාරකම් කෙරෙහි උනන්දුවක් දක්වන හෝ බලපෑමට ලක්වන පාර්ශ්ව වේ.\nඋදා: 1. හිමිකරුවන් 2. පාරිභෝගිකයින් 3. සේවකයින් 4. ණයහිමියන්/රජය.", "ව්‍යාපාරය සැමගේ යහපතට තුඩුදිය යුතුය.", "හිමිකරුවන්, පාරිභෝගිකයින්, සේවකයින්"),
    CardContentTuple("ව්‍යාපාරික ආචාර ධර්ම (Business Ethics) යනු මොනවාද?", "ව්‍යාපාර කටයුතු කිරීමේදී නීතියට පමණක් සීමා නොවී, පාරිභෝගිකයා, සේවකයින් සහ සමාජය නොරවටා සාධාරණව හා යුක්තිගරුකව ක්‍රියාකිරීමේ සදාචාරාත්මක මූලධර්මයි.", "දිගුකාලීන පාරිභෝගික විශ්වාසය දිනයි.", "සදාචාරාත්මක ව්‍යාපාර පැවැත්ම"),
    CardContentTuple("ආයතනික සමාජ වගකීම (CSR - Corporate Social Responsibility) යනු කුමක්ද?", "ව්‍යාපාරයක් තමන් උපයන ලාභයෙන් කොටසක් පරිසර සංරක්ෂණය, ප්‍රජා සුභසාධනය, අධ්‍යාපන ශිෂ්‍යත්ව හෝ සෞඛ්‍ය පහසුකම් සඳහා ස්වේච්ඡාවෙන් වැය කිරීමයි.", "තිරසාර සංවර්ධනයට රුකුල් දෙයි.", "CSR සමාජ සත්කාර"),
    CardContentTuple("ව්‍යාපාර වර්ගීකරණය කෙරෙන ප්‍රධාන ආර්ථික අංශ 3 මොනවාද?", "1. ප්‍රාථමික අංශය (කෘෂිකර්මය, පතල්, ධීවර - ස්වභාවික සම්පත් ලබාගැනීම)\n2. ද්විතීයික අංශය (කර්මාන්ත, ඉදිකිරීම් - අමුද්‍රව්‍ය නිමි භාණ්ඩ කිරීම)\n3. තෘතීයික අංශය (සේවා අංශය - වෙළඳාම, ප්‍රවාහනය, බැංකු).", "ආර්ථිකයේ ව්‍යුහය පෙන්වයි.", "ප්‍රාථමික, ද්විතීයික, තෘතීයික"),
    CardContentTuple("රාජ්‍ය අංශයේ ව්‍යාපාර සහ පෞද්ගලික අංශයේ ව්‍යාපාර අතර ප්‍රධාන වෙනස කුමක්ද?", "රාජ්‍ය අංශය = රජය සතු, මහජන සුභසාධනය ප්‍රධාන අරමුණ වූ ව්‍යාපාර (උදා: ලංගම, දුම්රිය, තැපැල්).\nපෞද්ගලික අංශය = පුද්ගලයන් සතු, උපරිම ලාභ ඉපැයීම මූලික අරමුණ වූ ව්‍යාපාර.", "හිමිකාරිත්වය හා අරමුණ අනුව වෙනස් වේ.", "රාජ්‍ය (සුභසාධන) vs පෞද්ගලික (ලාභ)"),
    CardContentTuple("ව්‍යාපාරයකට 'අවදානම' (Risk) ඇතිවන්නේ ඇයි? අවදානම් වර්ග 2ක් මොනවාද?", "අනාගතය අවිනිශ්චිත බැවින් ලාභ හෝ පාඩු සිදුවිය හැකිවීමයි. රක්ෂණය කළ හැකි අවදානම් (ගිනි, සොරකම්) සහ රක්ෂණය කළ නොහැකි අවදානම් (තරගය, විලාසිතා වෙනස්වීම්).", "ව්‍යවසායකයා අවදානම භාරගනී.", "රක්ෂණය කළ හැකි & නොහැකි අවදානම්"),
    CardContentTuple("දේශීය වෙළඳාම සහ ජාත්‍යන්තර වෙළඳාම අතර වෙනස කුමක්ද?", "දේශීය වෙළඳාම = රටක දේශසීමාව ඇතුළත දේශීය මුදලින් සිදුවන වෙළඳාම (තොග හා සිල්ලර).\nජාත්‍යන්තර වෙළඳාම = රටවල් අතර විදේශ විනිමය යොදාගනිමින් සිදුවන ආනයන, අපනයන සහ ප්‍රතිඅපනයන වෙළඳාම.", "භූගෝලීය සීමාව අනුව බෙදේ.", "දේශීය vs ජාත්‍යන්තර වෙළඳාම"),
    CardContentTuple("ප්‍රතිඅපනයන වෙළඳාම (Entrepot Trade) යනු කුමක්ද?", "භාණ්ඩයක් විදේශයකින් ආනයනය කර, දේශීයව පරිභෝජනය නොකර, යම් අගය එකතු කිරීමක් (ඇසුරුම් කිරීම හෝ පිරිසැකසුම්) සහිතව තවත් විදේශ රටකට නැවත අපනයනය කිරීමයි.", "ශ්‍රී ලංකාවේ තේ ඇසුරුම් ප්‍රතිඅපනයනය උදාහරණයකි.", "ආනයනය කර යළි අපනයනය කිරීම"),
    CardContentTuple("ව්‍යාපාරයක 'දැක්ම' (Vision) සහ 'මෙහෙවර' (Mission) යනු කුමක්ද?", "දැක්ම = ව්‍යාපාරය දිගුකාලීනව අනාගතයේ ළඟාවීමට අපේක්ෂා කරන උත්තරීතර සිහිනය/තත්ත්වය.\nමෙහෙවර = එම දැක්ම සාක්ෂාත් කරගැනීම සඳහා වර්තමානයේ ව්‍යාපාරය ඉටුකරන මූලික කාර්යභාරය හා පැවැත්මේ අරමුණයි.", "උපායමාර්ගික සැලසුම්කරණයේ පදනමයි.", "දැක්ම (අනාගතය) & මෙහෙවර (වර්තමානය)"),
    CardContentTuple("ඊ-වාණිජ්‍යය (E-Commerce) යනු කුමක්ද? එහි ප්‍රධාන වාසියක් කුමක්ද?", "අන්තර්ජාලය සහ විද්‍යුත් මාධ්‍ය උපයෝගී කරගනිමින් භාණ්ඩ හා සේවා මිලදී ගැනීම සහ විකිණීමයි. පැය 24 පුරා නිවසේ සිටම ගෝලීයව ගනුදෙනු කළ හැකිවීම ප්‍රධාන වාසියයි.", "භෞතික කඩසාප්පු අවශ්‍ය නොවේ.", "අන්තර්ජාලය හරහා වෙළඳාම"),
    CardContentTuple("නිෂ්පාදනය (Production) සහ ඵලදායිතාව (Productivity) අතර වෙනස කුමක්ද?", "නිෂ්පාදනය = නිමි භාණ්ඩ හා සේවාවල සමස්ත ප්‍රමාණයයි (ප්‍රතිදානය).\nඵලදායිතාව = යොදවන ලද යෙදවුම් ප්‍රමාණයට සාපේක්ෂව ලබාගත් ප්‍රතිදාන අනුපාතයයි (ප්‍රතිදානය / යෙදවුම්).", "අවම සම්පතකින් උපරිම නිමාවක් ලැබීම.", "නිෂ්පාදනය vs ඵලදායිතාව"),
